examples.template:
MonarchCollapsible(
    expanded = expanded,
    onExpandedChange = { expanded = it },
    label = {{label}},
    trailingIcon = {
        MonarchIcon(
            imageVector = SampleIcons.ChevronDown,
            contentDescription = null,
            size = MonarchIconSize.Sm,
        )
    },
) {
    MonarchText(text = {{content}})
}

